-- Phase C: persisted QA Lab and Customer #1 release gate.
create table if not exists public.autonomous_qa_scenarios(id uuid primary key default gen_random_uuid(),scenario_key text not null unique,source_type text not null check(source_type in('CHANGE','INCIDENT','INDUSTRY_CASE','REGRESSION')),title text not null,description text not null,target_role text not null check(target_role in('CLIENT','PROVIDER','ADMIN','SYSTEM','CROSS_ROLE')),service_id uuid,deterministic_judge jsonb not null default '{}'::jsonb,chaos_profile jsonb not null default '{}'::jsonb,seeded_defect boolean not null default false,status text not null default 'ACTIVE' check(status in('DRAFT','ACTIVE','RETIRED')),created_by uuid default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.autonomous_qa_runs(id uuid primary key default gen_random_uuid(),scenario_id uuid not null references public.autonomous_qa_scenarios(id),correlation_id uuid not null default gen_random_uuid(),status text not null default 'QUEUED' check(status in('QUEUED','RUNNING','PASSED','FAILED','BLOCKED')),simulator_results jsonb not null default '{}'::jsonb,chaos_result jsonb not null default '{}'::jsonb,judge_result jsonb not null default '{}'::jsonb,diagnosis text,remediation_request text,permanent_regression boolean not null default false,started_at timestamptz,finished_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.autonomous_quality_coverage(id uuid primary key default gen_random_uuid(),coverage_key text not null unique,domain text not null,requirement text not null,scenario_id uuid references public.autonomous_qa_scenarios(id),last_run_id uuid references public.autonomous_qa_runs(id),status text not null default 'UNCOVERED' check(status in('UNCOVERED','COVERED','FAILING','BLOCKED')),updated_at timestamptz not null default now());
create table if not exists public.autonomous_release_gate(id uuid primary key default gen_random_uuid(),gate_key text not null unique,status text not null default 'BLOCKED' check(status in('BLOCKED','READY')),blockers jsonb not null default '[]'::jsonb,evaluated_at timestamptz not null default now(),evaluated_by uuid default auth.uid());
alter table public.autonomous_qa_scenarios enable row level security;alter table public.autonomous_qa_runs enable row level security;alter table public.autonomous_quality_coverage enable row level security;alter table public.autonomous_release_gate enable row level security;
do $$ begin create policy qa_scenarios_superadmin_read on public.autonomous_qa_scenarios for select to authenticated using(private.is_superadmin());create policy qa_runs_superadmin_read on public.autonomous_qa_runs for select to authenticated using(private.is_superadmin());create policy qa_coverage_superadmin_read on public.autonomous_quality_coverage for select to authenticated using(private.is_superadmin());create policy release_gate_superadmin_read on public.autonomous_release_gate for select to authenticated using(private.is_superadmin());exception when duplicate_object then null;end $$;
create or replace function public.superadmin_create_qa_scenario(p_scenario_key text,p_source_type text,p_title text,p_description text,p_target_role text,p_deterministic_judge jsonb default '{}'::jsonb,p_chaos_profile jsonb default '{}'::jsonb,p_seeded_defect boolean default false) returns public.autonomous_qa_scenarios language plpgsql security definer set search_path=public,private,auth as $$declare v public.autonomous_qa_scenarios%rowtype;begin if auth.uid() is null or not private.is_superadmin() then raise exception 'SUPERADMIN_REQUIRED' using errcode='42501';end if;insert into public.autonomous_qa_scenarios(scenario_key,source_type,title,description,target_role,deterministic_judge,chaos_profile,seeded_defect) values(p_scenario_key,p_source_type,p_title,p_description,p_target_role,p_deterministic_judge,p_chaos_profile,p_seeded_defect) on conflict(scenario_key) do update set title=excluded.title,description=excluded.description,deterministic_judge=excluded.deterministic_judge,chaos_profile=excluded.chaos_profile,seeded_defect=excluded.seeded_defect,updated_at=now() returning * into v;return v;end$$;
create or replace function public.superadmin_evaluate_release_gate(p_gate_key text default 'CUSTOMER_1') returns public.autonomous_release_gate language plpgsql security definer set search_path=public,private,auth as $$declare b jsonb:='[]'::jsonb;v public.autonomous_release_gate%rowtype;begin if auth.uid() is null or not private.is_superadmin() then raise exception 'SUPERADMIN_REQUIRED' using errcode='42501';end if;if exists(select 1 from public.autonomous_audit_findings where severity='CRITICAL' and status<>'CLOSED')then b=b||'["OPEN_CRITICAL_FINDING"]'::jsonb;end if;if exists(select 1 from public.autonomous_quality_coverage where status<>'COVERED')or not exists(select 1 from public.autonomous_quality_coverage)then b=b||'["QA_COVERAGE_INCOMPLETE"]'::jsonb;end if;if exists(select 1 from public.autonomous_qa_runs where status in('FAILED','BLOCKED'))then b=b||'["QA_RUN_FAILURE"]'::jsonb;end if;if exists(select 1 from public.autonomous_jobs where status='RUNNING' and lease_expires_at<now())then b=b||'["STALE_AUTONOMOUS_JOB"]'::jsonb;end if;insert into public.autonomous_release_gate(gate_key,status,blockers,evaluated_at,evaluated_by)values(p_gate_key,case when jsonb_array_length(b)=0 then'READY'else'BLOCKED'end,b,now(),auth.uid())on conflict(gate_key)do update set status=excluded.status,blockers=excluded.blockers,evaluated_at=now(),evaluated_by=auth.uid() returning * into v;return v;end$$;
revoke all on function public.superadmin_create_qa_scenario(text,text,text,text,text,jsonb,jsonb,boolean) from public;grant execute on function public.superadmin_create_qa_scenario(text,text,text,text,text,jsonb,jsonb,boolean) to authenticated;revoke all on function public.superadmin_evaluate_release_gate(text) from public;grant execute on function public.superadmin_evaluate_release_gate(text) to authenticated;
insert into public.autonomous_quality_coverage(coverage_key,domain,requirement)values('service-lifecycle','journey','Complete service lifecycle by serviceId'),('provider-radius','matching','Provider alert radius <=20km'),('gps-geofence','location','Recent valid GPS and backend geofence'),('permissions-rls','security','RLS/RPC ownership and permissions'),('payments','finance','Payment and debt reconciliation'),('realtime','integration','Realtime state propagation'),('roles','roles','Client Provider Admin role isolation')on conflict(coverage_key)do nothing;